<script setup lang="ts">import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import InputError from '@/Components/InputError.vue'; import ValidationSummary from '@/Components/ValidationSummary.vue'; import {Head,useForm,router} from '@inertiajs/vue3'; import {reactive} from 'vue'; const props=defineProps<{customers:any[];filters:any}>(); const filters=reactive({...props.filters}); const apply=()=>router.get(route('admin.customers.index'),filters,{preserveState:true,replace:true}); const reset=()=>{filters.search='';apply()}; const form=useForm({name:'',contact_name:'',email:'',phone:'',is_active:true}); const edit=(customer:any)=>{const name=window.prompt('Customer name',customer.name);if(name)router.put(route('admin.customers.update',customer.id),{...customer,name});};</script>
<template><Head title="Customers"/><AuthenticatedLayout><template #header><h2 class="text-xl font-semibold">Customers</h2></template><div class="mx-auto max-w-5xl space-y-5 p-6"><form @submit.prevent="form.post(route('admin.customers.store'))" class="grid gap-2 bg-white p-4 shadow sm:grid-cols-4"><div><input v-model="form.name" placeholder="Customer name" required class="w-full rounded border-gray-300"><InputError :message="form.errors.name" class="mt-1"/></div><div><input v-model="form.contact_name" placeholder="Contact name" class="w-full rounded border-gray-300"><InputError :message="form.errors.contact_name" class="mt-1"/></div><div><input v-model="form.email" placeholder="Email" class="w-full rounded border-gray-300"><InputError :message="form.errors.email" class="mt-1"/></div><button class="rounded bg-indigo-600 text-white">Add customer</button><div class="sm:col-span-4"><ValidationSummary :errors="form.errors"/></div></form><form @submit.prevent="apply" class="flex gap-2"><input v-model="filters.search" placeholder="Search name, email, phone" class="rounded border-gray-300"><button class="rounded bg-gray-800 px-3 text-white">Search</button><button type="button" @click="reset" class="text-gray-600">Reset</button></form><div class="bg-white shadow"><div v-for="customer in customers" :key="customer.id" class="flex justify-between border-b p-4"><span><b>{{customer.name}}</b> — {{customer.contact_name}} <span class="text-sm text-gray-500">{{customer.users_count}} users, {{customer.events_count}} events</span></span><button @click="edit(customer)" class="text-indigo-600">Edit name</button></div><p v-if="!customers.length" class="p-4 text-gray-600">No customers match your search.</p></div></div></AuthenticatedLayout></template>
